'use client';

import { useState, useEffect } from 'react';
import { Badge } from '@/components/ui/Badge';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { getTenantIntegrationsAction, testIntegrationConnectionAction, updateIntegrationCredentialsAction, deleteIntegrationAction } from '@/modules/settings/integration.actions';
import { Loader2, Settings, AlertCircle, CheckCircle2, Trash2, Plug } from 'lucide-react';
import { formatDistanceToNow } from 'date-fns';
import { toast } from 'sonner';

const REQUIRED_PROVIDERS = [
  { id: 'TELEPHONY', name: 'Calling', description: 'Voice and telephony infrastructure' },
  { id: 'INTERNAL_CHAT', name: 'Internal Chat', description: 'Realtime messaging' },
  { id: 'VIDEO', name: 'Video Meetings', description: 'WebRTC video rooms' },
  { id: 'STORAGE', name: 'File Storage', description: 'Document and media storage' },
  { id: 'EMAIL', name: 'Email', description: 'Outbound and inbound parsing' }
];

export default function IntegrationsPage() {
   
  // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: Legacy internal payload requires architectural typing
  const [integrations, setIntegrations] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [isUpdating, setIsUpdating] = useState(false);
  
   
  // Dialog state
  // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: Legacy internal payload requires architectural typing
  const [selectedProvider, setSelectedProvider] = useState<any>(null);
  const [credentialsJson, setCredentialsJson] = useState('');

  const load = async () => {
    const res = await getTenantIntegrationsAction();
    if (res.success && res.data) {
      setIntegrations(res.data);
    }
    setLoading(false);
  };

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect -- State setter inside effect retained for deterministic data fetching flow.
    load();
  }, []);

  const getIntegrationData = (providerType: string) => {
    return integrations.find(i => i.provider === providerType);
   
  };

  // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: External provider boundary lacks strict types
  const handleTestConnection = async (providerType: any) => {
    toast.info('Testing connection...');
    const res = await testIntegrationConnectionAction(providerType);
    if (res.success) {
      toast.success('Connection successful');
      load();
    } else {
      toast.error(res.error || 'Connection failed');
    }
  };

  const handleSaveCredentials = async () => {
    if (!selectedProvider) return;
    setIsUpdating(true);
    const res = await updateIntegrationCredentialsAction(selectedProvider.id, credentialsJson);
    if (res.success) {
      toast.success('Credentials updated securely');
      load();
      setSelectedProvider(null);
    } else {
      toast.error(res.error || 'Update failed');
    }
     
    setIsUpdating(false);
  };

  // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: External provider boundary lacks strict types
  const handleDelete = async (providerType: any) => {
    const res = await deleteIntegrationAction(providerType);
    if (res.success) {
      toast.success('Integration removed');
      load();
    } else {
      toast.error(res.error || 'Failed to remove');
    }
  };

  if (loading) {
    return (
      <div className="flex h-[400px] items-center justify-center">
        <Loader2 className="w-8 h-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <div className="space-y-6 max-w-6xl mx-auto py-8 px-4 sm:px-6 lg:px-8">
      {/* Header Panel */}
      <div className="glass-panel p-6 sm:p-8 relative overflow-hidden group">
        <div className="absolute inset-0 bg-gradient-to-br from-[#7C5CFC]/5 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500" />
        <div className="relative z-10 flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-display font-bold text-white tracking-tight">Communication Providers</h1>
            <p className="text-sm text-[#8891B0] mt-1">Manage your infrastructure providers and credentials. Integrations are isolated by department.</p>
          </div>
          <div className="hidden sm:flex w-12 h-12 rounded-2xl bg-cyan-500/10 items-center justify-center border border-cyan-500/20">
            <Plug className="w-6 h-6 text-cyan-400" />
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {REQUIRED_PROVIDERS.map((providerDef) => {
          const integration = getIntegrationData(providerDef.id);
          const isDemo = !integration;

          return (
            <div key={providerDef.id} className="glass-panel p-6 flex flex-col h-full transition-all duration-300 hover:border-white/10 hover:shadow-2xl hover:shadow-violet-500/5 group">
              <div className="flex justify-between items-start mb-4">
                <div>
                  <h3 className="text-base font-display font-semibold text-white">{providerDef.name}</h3>
                  <div className="text-xs text-[#8891B0] mt-0.5">{providerDef.description}</div>
                </div>
                <Badge variant={isDemo ? 'slate' : 'violet'}>
                  {isDemo ? 'Demo Mode' : 'Production'}
                </Badge>
              </div>

              <div className="flex-1 space-y-4 mb-6">
                {isDemo ? (
                  <div className="bg-[#0D1326]/50 p-4 rounded-xl border border-white/[.04] text-xs text-[#8891B0] leading-relaxed">
                    Currently using the default Demo Provider. Simulated records will be generated automatically.
                  </div>
                ) : (
                  <div className="space-y-3 bg-[#0D1326]/30 p-4 rounded-xl border border-white/[.02]">
                    <div className="flex items-center gap-2 text-sm">
                      {integration.status === 'ACTIVE' ? (
                        <CheckCircle2 className="w-4 h-4 text-emerald-400" />
                      ) : (
                        <AlertCircle className="w-4 h-4 text-rose-400" />
                      )}
                      <span className="font-medium text-[#E7EAF5]">
                        Status: <span className={integration.status === 'ACTIVE' ? 'text-emerald-400' : 'text-rose-400'}>{integration.status}</span>
                      </span>
                    </div>
                    
                    <div className="text-xs text-[#8891B0]">
                      Credentials are masked and encrypted (AES-256-GCM).
                    </div>
                    
                    {integration.lastCheckedAt && (
                      <div className="text-[10px] text-[#8891B0]/70 font-mono">
                        Last checked: {formatDistanceToNow(new Date(integration.lastCheckedAt), { addSuffix: true })}
                      </div>
                    )}
                  </div>
                )}
              </div>

              <div className="pt-4 border-t border-white/[.04] flex gap-2 mt-auto">
                <Dialog open={selectedProvider?.id === providerDef.id} onOpenChange={(open) => !open && setSelectedProvider(null)}>
                  <DialogTrigger render={<Button variant="ghost" size="sm" className="flex-1 gap-2 bg-white/5 hover:bg-white/10" onClick={() => setSelectedProvider(providerDef)} />}>
                    <Settings className="w-4 h-4" />
                    Configure
                  </DialogTrigger>
                  <DialogContent>
                    <DialogHeader>
                      <DialogTitle>Configure {providerDef.name} Credentials</DialogTitle>
                    </DialogHeader>
                    <div className="space-y-4 py-4">
                      <div className="text-sm text-[#8891B0]">
                        Enter credentials as a JSON object (e.g. `&#123;&quot;provider&quot;:&quot;twilio&quot;,&quot;sid&quot;:&quot;...&quot;&#125;`). 
                        Secrets will be encrypted immediately and are never returned to the frontend.
                      </div>
                      <Input 
                        placeholder='{"provider": "twilio", "key": "secret"}' 
                        value={credentialsJson}
                        onChange={e => setCredentialsJson(e.target.value)}
                      />
                      <div className="flex justify-end gap-2 pt-4">
                        <Button variant="ghost" onClick={() => setSelectedProvider(null)}>Cancel</Button>
                        <Button onClick={handleSaveCredentials} disabled={isUpdating || !credentialsJson}>
                          {isUpdating && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                          Save Securely
                        </Button>
                      </div>
                    </div>
                  </DialogContent>
                // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: Legacy internal payload requires architectural typing
                </Dialog>

                {!isDemo && (
                   
                  <>
                    // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: External provider boundary lacks strict types
                    <Button variant="ghost" size="icon" className="bg-white/5 hover:bg-white/10 hover:text-cyan-400" onClick={() => handleTestConnection(providerDef.id as any)} title="Test Connection">
                      <Plug className="w-4 h-4" />
                    </Button>
                    // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: External provider boundary lacks strict types
                    <Button variant="danger" size="icon" onClick={() => handleDelete(providerDef.id as any)} title="Remove Integration">
                      <Trash2 className="w-4 h-4" />
                    </Button>
                  </>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

'use client';
import { useState, useTransition } from 'react';
import { Edit2, Plus, UserPlus } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { 
    createTerritoryAction, 
    updateTerritoryAction, 
    assignTerritoryUserAction, 
    removeTerritoryAssignmentAction 
} from '@/modules/sales-intelligence/actions/territory.actions';
import { toast } from 'sonner';

 
// eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: Legacy internal payload requires architectural typing
export function TerritoriesClient({ territories, canManage }: { territories: any[], canManage: boolean }) {
  const [isPending, startTransition] = useTransition();
  const [isAdding, setIsAdding] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [assigningId, setAssigningId] = useState<string | null>(null);

  const [formData, setFormData] = useState({ name: '', description: '', parentId: '' });
  const [assignData, setAssignData] = useState({ targetUserId: '', role: 'REP' });

  const handleCreate = async () => {
    if (!formData.name) {
        toast.error('Name is required');
        return;
    }
    startTransition(async () => {
      const result = await createTerritoryAction({
        name: formData.name,
        description: formData.description || undefined,
        parentId: formData.parentId || undefined
      });
      if (result.success) {
        toast.success('Territory created');
        setIsAdding(false);
        setFormData({ name: '', description: '', parentId: '' });
        window.location.reload();
      } else {
        toast.error(result.error);
      }
    });
  };

  const handleUpdate = async () => {
    if (!editingId) return;
    startTransition(async () => {
      const result = await updateTerritoryAction(editingId, {
        name: formData.name,
        description: formData.description || undefined,
        parentId: formData.parentId || undefined
      });
      if (result.success) {
        toast.success('Territory updated');
        setEditingId(null);
        window.location.reload();
      } else {
        toast.error(result.error);
      }
    });
  };

  const handleAssign = async () => {
    if (!assigningId || !assignData.targetUserId) {
        toast.error('User ID is required');
        return;
    }
    startTransition(async () => {
      const result = await assignTerritoryUserAction({
        territoryId: assigningId,
        targetUserId: assignData.targetUserId,
        role: assignData.role
      });
      if (result.success) {
        toast.success('User assigned');
        setAssigningId(null);
        setAssignData({ targetUserId: '', role: 'REP' });
        window.location.reload();
      } else {
        toast.error(result.error);
      }
    });
  };

  // eslint-disable-next-line @typescript-eslint/no-unused-vars -- S2 Residual Debt: Legacy unused local
  const handleRemoveAssignment = async (assignmentId: string) => {
    if (!confirm('Are you sure you want to remove this assignment?')) return;
    startTransition(async () => {
      const result = await removeTerritoryAssignmentAction(assignmentId);
      if (result.success) {
        toast.success('Assignment removed');
        window.location.reload();
      } else {
        toast.error(result.error);
      }
    });
  };

  return (
    <div className="space-y-4">
      {canManage && (
        <div className="flex justify-end">
          <Button onClick={() => { setIsAdding(true); setEditingId(null); setAssigningId(null); setFormData({ name: '', description: '', parentId: '' }); }} disabled={isPending}>
            <Plus className="w-4 h-4 mr-2" /> Add Territory
          </Button>
        </div>
      )}

      {(isAdding || editingId) && canManage && (
        <div className="glass-panel p-4 mb-4 rounded-xl flex flex-col gap-4 border border-white/10 bg-white/5">
          <h3 className="font-semibold text-white">{editingId ? 'Edit Territory' : 'New Territory'}</h3>
          <input 
             type="text" 
             placeholder="Territory Name" 
             value={formData.name}
             onChange={e => setFormData(prev => ({ ...prev, name: e.target.value }))}
             className="w-full bg-black/20 border border-white/10 rounded px-3 py-2 text-white text-sm"
          />
          <input 
             type="text" 
             placeholder="Description" 
             value={formData.description}
             onChange={e => setFormData(prev => ({ ...prev, description: e.target.value }))}
             className="w-full bg-black/20 border border-white/10 rounded px-3 py-2 text-white text-sm"
          />
          <input 
             type="text" 
             placeholder="Parent Territory ID (Optional)" 
             value={formData.parentId}
             onChange={e => setFormData(prev => ({ ...prev, parentId: e.target.value }))}
             className="w-full bg-black/20 border border-white/10 rounded px-3 py-2 text-white text-sm"
          />
          <div className="flex gap-2 justify-end">
            <Button variant="ghost" onClick={() => { setIsAdding(false); setEditingId(null); }}>Cancel</Button>
            <Button onClick={editingId ? handleUpdate : handleCreate} disabled={isPending}>
                {isPending ? 'Saving...' : 'Save'}
            </Button>
          </div>
        </div>
      )}

      {assigningId && canManage && (
        <div className="glass-panel p-4 mb-4 rounded-xl flex flex-col gap-4 border border-white/10 bg-white/5">
          <h3 className="font-semibold text-white">Assign User to Territory</h3>
          <input 
             type="text" 
             placeholder="User ID" 
             value={assignData.targetUserId}
             onChange={e => setAssignData(prev => ({ ...prev, targetUserId: e.target.value }))}
             className="w-full bg-black/20 border border-white/10 rounded px-3 py-2 text-white text-sm"
          />
          <input 
             type="text" 
             placeholder="Role (e.g. REP, MANAGER)" 
             value={assignData.role}
             onChange={e => setAssignData(prev => ({ ...prev, role: e.target.value }))}
             className="w-full bg-black/20 border border-white/10 rounded px-3 py-2 text-white text-sm"
          />
          <div className="flex gap-2 justify-end">
            <Button variant="ghost" onClick={() => { setAssigningId(null); }}>Cancel</Button>
            <Button onClick={handleAssign} disabled={isPending}>
                {isPending ? 'Assigning...' : 'Assign'}
            </Button>
          </div>
        </div>
      )}

      <div className="overflow-x-auto">
        <table className="w-full text-left text-sm">
          <thead>
            <tr className="border-b border-white/[.04] bg-[#0D1326]/50">
              <th className="px-6 py-4 font-semibold text-[#8891B0] uppercase tracking-wider text-[10px]">Territory Name</th>
              <th className="px-6 py-4 font-semibold text-[#8891B0] uppercase tracking-wider text-[10px]">Owner / Assignments</th>
              <th className="px-6 py-4 font-semibold text-[#8891B0] uppercase tracking-wider text-[10px]">Parent</th>
              {canManage && <th className="px-6 py-4 font-semibold text-[#8891B0] uppercase tracking-wider text-[10px] text-right">Actions</th>}
            </tr>
          // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: Legacy internal payload requires architectural typing
          </thead>
          <tbody className="divide-y divide-white/[.04]">
            // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: Legacy internal payload requires architectural typing
            {territories?.map((territory: any) => (
              <tr key={territory.id} className="hover:bg-white/[.02] transition-colors group">
                <td className="px-6 py-4">
                  <p className="font-medium text-white">{territory.name}</p>
                  <p className="text-xs text-[#8891B0]">{territory.description}</p>
                  <p className="text-[10px] text-[#8891B0] opacity-50 font-mono mt-1">ID: {territory.id}</p>
                </td>
                <td className="px-6 py-4 text-[#8891B0]">
                    {/* The API returns userTerritories if queried correctly, but the basic findMany just returns the flat territory */}
                    {/* Assuming territory.owner or userTerritories is populated, if not it just shows basic info */}
                    {territory.owner?.email || 'Unassigned'}
                    {/* If there's assignments data we could map it here, but we will just show the assign button for now */}
                </td>
                <td className="px-6 py-4 text-[#8891B0]">
                    {territory.parentId || '-'}
                </td>
                {canManage && (
                  <td className="px-6 py-4 text-right">
                    <div className="flex justify-end gap-2">
                        <Button 
                            variant="ghost" 
                            size="sm" 
                            onClick={() => { 
                                setAssigningId(territory.id);
                                setIsAdding(false);
                                setEditingId(null);
                            }}
                            disabled={isPending}
                        >
                            <UserPlus className="w-4 h-4 text-[#8891B0]" />
                        </Button>
                        <Button 
                            variant="ghost" 
                            size="sm" 
                            onClick={() => { 
                                setEditingId(territory.id); 
                                setIsAdding(false); 
                                setAssigningId(null);
                                setFormData({ name: territory.name, description: territory.description || '', parentId: territory.parentId || '' }); 
                            }}
                            disabled={isPending}
                        >
                            <Edit2 className="w-4 h-4 text-[#8891B0]" />
                        </Button>
                    </div>
                  </td>
                )}
              </tr>
            ))}
            {(!territories || territories.length === 0) && (
              <tr>
                <td colSpan={canManage ? 4 : 3} className="px-6 py-8 text-center text-[#8891B0]">
                  No territories found.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

import { notFound } from 'next/navigation';
import { getTicketByIdAction } from '@/modules/support/actions/ticket.actions';
import { Badge } from '@/components/ui/Badge';
