'use client';

import React, { useState, useEffect } from 'react';
import { Phone, User as UserIcon } from 'lucide-react';
import { initiateCallAction } from '@/modules/communication/actions/call.actions';
import { getPresenceAction } from '@/modules/communication/actions/presence.actions';

const MOCK_USERS = [
  { id: '123e4567-e89b-12d3-a456-426614174000', firstName: 'Alice', lastName: 'Admin' },
  { id: '987fcdeb-51a2-43d7-9012-345678901234', firstName: 'Bob', lastName: 'Employee' },
];

export default function CallDirectory({ userId, tenantId }: { userId: string, tenantId: string }) {
  const [users, setUsers] = useState<any[]>(MOCK_USERS); // We would fetch tenant users here, but we can simulate a list for the UI skeleton
  const [presences, setPresences] = useState<Record<string, any>>({});
  const [callingId, setCallingId] = useState<string | null>(null);

  useEffect(() => {
    // This is where we'd fetch tenant users via a server action. 
    // For now, assume we have an action or we just list the current user as a test target.
    // In a real implementation, we'd fetch actual users.

    const fetchPresence = async () => {
      try {
        const res = await getPresenceAction(MOCK_USERS.map(u => u.id));
        if (res.success) {
          const pMap: Record<string, any> = {};
          res.data.forEach((p: any) => pMap[p.userId] = p);
          setPresences(pMap);
        }
      } catch (e) {
        console.error(e);
      }
    };
    fetchPresence();
  }, []);

  const handleCall = async (recipientId: string) => {
    setCallingId(recipientId);
    try {
      await initiateCallAction(recipientId);
      // The WebRTCCallManager will pick up the active state and show the calling UI automatically
    } catch (e) {
      console.error('Call failed', e);
      alert('Could not initiate call');
    } finally {
      setCallingId(null);
    }
  };

  return (
    <div className="bg-white border rounded-lg shadow-sm p-6 max-w-2xl mx-auto mt-6">
      <h2 className="text-xl font-semibold mb-4 text-gray-800">Internal Directory</h2>
      <div className="space-y-4">
        {users.map(u => {
          const presence = presences[u.id];
          const isOnline = presence?.status === 'ONLINE';

          return (
            <div key={u.id} className="flex items-center justify-between p-4 bg-gray-50 rounded-lg border">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 bg-gray-200 rounded-full flex items-center justify-center relative">
                  <UserIcon className="w-6 h-6 text-gray-500" />
                  <span className={`absolute bottom-0 right-0 w-3 h-3 rounded-full border-2 border-white ${isOnline ? 'bg-emerald-500' : 'bg-gray-400'}`}></span>
                </div>
                <div>
                  <h3 className="font-medium text-gray-900">{u.firstName} {u.lastName}</h3>
                  <p className="text-sm text-gray-500">{isOnline ? 'Online' : 'Offline'}</p>
                </div>
              </div>
              <button
                onClick={() => handleCall(u.id)}
                disabled={callingId === u.id || u.id === userId}
                className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded hover:bg-indigo-700 disabled:opacity-50 transition-colors"
              >
                <Phone className="w-4 h-4" />
                {callingId === u.id ? 'Calling...' : 'Call'}
              </button>
            </div>
          );
        })}
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect, useRef } from 'react';
import { Send, User as UserIcon, Phone } from 'lucide-react';
import Pusher from 'pusher-js';
import { getConversationsAction, getMessagesAction, sendMessageAction } from '@/modules/communication/actions/chat.actions';

export default function ChatInterface({ userId, tenantId }: { userId: string; tenantId: string }) {
  const [conversations, setConversations] = useState<any[]>([]);
  const [activeConvId, setActiveConvId] = useState<string | null>(null);
  const [messages, setMessages] = useState<any[]>([]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(true);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // Load conversations
    getConversationsAction().then(res => {
      if (res.success) {
        setConversations(res.data);
      }
      setLoading(false);
    }).catch(err => {
      console.error('Failed to load conversations:', err);
      setLoading(false);
    });
  }, []);

  useEffect(() => {
    if (!activeConvId) return;

    // Load messages
    getMessagesAction(activeConvId).then(res => {
      if (res.success) setMessages(res.data);
    });

    // Setup Pusher
    const pusherKey = process.env.NEXT_PUBLIC_PUSHER_KEY;
    if (!pusherKey) {
      console.warn('NEXT_PUBLIC_PUSHER_KEY missing; realtime chat disabled.');
      return;
    }

    const pusher = new Pusher(pusherKey, {
      cluster: process.env.NEXT_PUBLIC_PUSHER_CLUSTER || 'mt1',
      authEndpoint: '/api/realtime/auth',
    });

    const channelName = `private-chat-tenant_${tenantId}_conv_${activeConvId}`;
    const channel = pusher.subscribe(channelName);

    channel.bind('new_message', (data: any) => {
      setMessages(prev => [...prev, data]);
    });

    return () => {
      channel.unbind_all();
      pusher.unsubscribe(channelName);
      pusher.disconnect();
    };
  }, [activeConvId, tenantId]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || !activeConvId) return;
    const content = input;
    setInput('');
    try {
      const res = await sendMessageAction({ conversationId: activeConvId, content });
      if (res && res.success && res.data) {
        setMessages(prev => {
          if (prev.find(m => m.id === res.data.id)) return prev;
          return [...prev, res.data];
        });
      }
    } catch (e) {
      console.error(e);
      // rollback or show error
    }
  };

  if (loading) return <div className="p-6 text-center text-gray-500">Loading...</div>;

  return (
    <div className="flex h-[700px] bg-white border rounded-lg shadow-sm overflow-hidden">
      {/* Sidebar */}
      <div className="w-1/3 border-r flex flex-col">
        <div className="p-4 border-b font-semibold bg-gray-50 text-gray-800">
          Conversations
        </div>
        <div className="flex-1 overflow-y-auto">
          {conversations.length === 0 ? (
            <div className="p-4 text-center text-gray-500 text-sm">No conversations found.</div>
          ) : (
            conversations.map(c => (
              <div 
                key={c.id} 
                onClick={() => setActiveConvId(c.id)}
                className={`p-4 border-b cursor-pointer hover:bg-gray-50 transition-colors ${activeConvId === c.id ? 'bg-indigo-50 border-l-4 border-l-indigo-500' : ''}`}
              >
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-gray-200 rounded-full flex items-center justify-center">
                    <UserIcon className="w-5 h-5 text-gray-500" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="font-medium text-gray-900 truncate">{c.name || 'Chat'}</p>
                    <p className="text-sm text-gray-500 truncate">Tap to view</p>
                  </div>
                </div>
              </div>
            ))
          )}
        </div>
      </div>

      {/* Main Chat Area */}
      <div className="flex-1 flex flex-col">
        {activeConvId ? (
          <>
            <div className="p-4 border-b font-semibold bg-gray-50 text-gray-800 flex items-center justify-between">
              <span>Active Conversation</span>
              {conversations.find(c => c.id === activeConvId)?.targetUserId && (
                <button
                  onClick={() => {
                    const targetUserId = conversations.find(c => c.id === activeConvId)?.targetUserId;
                    if (targetUserId) {
                      window.dispatchEvent(new CustomEvent('webrtc-initiate-call', { detail: { targetUserId } }));
                    }
                  }}
                  className="flex items-center gap-1.5 px-3 py-1.5 text-sm bg-indigo-50 text-indigo-600 hover:bg-indigo-100 rounded-md transition-colors font-medium"
                >
                  <Phone className="w-4 h-4" />
                  Call
                </button>
              )}
            </div>
            <div className="flex-1 p-4 overflow-y-auto bg-gray-50/50">
              {messages.length === 0 ? (
                <div className="h-full flex items-center justify-center text-gray-500">
                  No messages yet. Say hello!
                </div>
              ) : (
                <div className="space-y-4">
                  {messages.map(m => {
                    const isMine = m.senderId === userId;
                    return (
                      <div key={m.id} className={`flex ${isMine ? 'justify-end' : 'justify-start'}`}>
                        <div className={`max-w-[70%] rounded-2xl px-4 py-2 ${isMine ? 'bg-indigo-600 text-white rounded-br-none' : 'bg-white border text-gray-900 rounded-bl-none shadow-sm'}`}>
                          <p>{m.content}</p>
                          {m.referenceType && m.referenceId && (
                            <div className="mt-2 text-xs bg-black/10 p-2 rounded">
                              Referenced {m.referenceType}: {m.referenceId}
                            </div>
                          )}
                        </div>
                      </div>
                    );
                  })}
                  <div ref={messagesEndRef} />
                </div>
              )}
            </div>
            <div className="p-4 border-t bg-white">
              <form 
                className="flex items-center gap-2"
                onSubmit={(e) => { e.preventDefault(); handleSend(); }}
              >
                <input 
                  type="text" 
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  placeholder="Type a message..." 
                  className="flex-1 bg-gray-100 border-transparent rounded-full px-4 py-2 focus:ring-2 focus:ring-indigo-500 focus:bg-white transition-colors"
                />
                <button 
                  type="submit" 
                  disabled={!input.trim()}
                  className="p-2 bg-indigo-600 text-white rounded-full hover:bg-indigo-700 disabled:opacity-50 transition-colors"
                >
                  <Send className="w-5 h-5" />
                </button>
              </form>
            </div>
          </>
        ) : (
          <div className="flex-1 flex items-center justify-center bg-gray-50/50">
            <p className="text-gray-500">Select a conversation to start messaging.</p>
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { Send, User as UserIcon, Archive } from 'lucide-react';
import { getInboxAction, sendInternalMailAction, archiveMailAction } from '@/modules/communication/actions/inbox.actions';

export default function MailInterface({ userId }: { userId: string }) {
  const [inbox, setInbox] = useState<any[]>([]);
  const [activeMail, setActiveMail] = useState<any | null>(null);
  const [compose, setCompose] = useState(false);
  const [loading, setLoading] = useState(true);

  // Compose states
  const [subject, setSubject] = useState('');
  const [body, setBody] = useState('');
  const [toStr, setToStr] = useState(''); // Comma separated userIds for prototype
  const [sending, setSending] = useState(false);

  const loadInbox = React.useCallback(async () => {
    const res = await getInboxAction();
    if (res.success) {
      setInbox(res.data);
    }
    setLoading(false);
  }, []);

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect -- False positive: loadInbox contains only asynchronous setState after network fetch
    loadInbox();
  }, [loadInbox]);



  const handleSend = async () => {
    if (!subject || !body || !toStr) return;
    setSending(true);
    try {
      const toIds = toStr.split(',').map(s => s.trim()).filter(Boolean);
      await sendInternalMailAction({
        subject,
        bodyHtml: body,
        toIds
      });
      setCompose(false);
      setSubject('');
      setBody('');
      setToStr('');
      loadInbox();
    } catch (e) {
      console.error(e);
    } finally {
      setSending(false);
    }
  };

  const handleArchive = async (messageId: string) => {
    try {
      await archiveMailAction(messageId);
      setActiveMail(null);
      loadInbox();
    } catch (e) {
      console.error(e);
    }
  };

  if (loading) return <div className="p-6 text-center text-gray-500">Loading mailbox...</div>;

  return (
    <div className="flex h-[700px] bg-white border rounded-lg shadow-sm overflow-hidden">
      {/* Sidebar */}
      <div className="w-1/3 border-r flex flex-col">
        <div className="p-4 border-b font-semibold bg-gray-50 text-gray-800 flex justify-between items-center">
          <span>Inbox</span>
          <button 
            onClick={() => setCompose(true)}
