                    <select 
                      required
                      name="assignedUserId"
                                          defaultValue={deal.assignedUserId || ''}
                      className="w-full text-sm transition-all focus:ring-2 focus:ring-[#7C5CFC] focus:border-transparent text-white"
                      style={{
