export async function generateStreamToken(cameraId: string) {
  if (!ENV.cctvEnabled) {
    throw new Error('CCTV module is disabled');
  }

  const user = await requireAuth();
  const tenantId = await requireTenant();
  
  await requirePermission('STREAM', 'READ');

  if (rateLimiters.cctvStream) {
    try {
      const { success } = await rateLimiters.cctvStream.limit(`${tenantId}:${user.id}:${cameraId}`);
      if (!success) {
        throw new Error('Too many stream requests. Please wait before requesting a new stream token.');
      }
    } catch (e: any) {
      if (e.message !== 'Too many stream requests. Please wait before requesting a new stream token.') {
         // Fallback if redis is down: Fail closed for security limits? Wait, the prompt says "Redis/rate-limiter failure behavior must be explicitly determined". We will fail closed to prevent abuse when redis is down.
         Logger.error('CCTV stream rate limiter failure:', e);
         throw new Error('Stream token service temporarily unavailable due to rate limiter outage.');
      }
      throw e;
    }
  }

  return await globalPrisma.$transaction(async (baseTx) => {
    const tx = await withTenantTransaction(baseTx, tenantId);
    
    // Include credential in the query securely
    const camera = await tx.camera.findFirst({
      where: { id: cameraId, tenantId, deletedAt: null },
      include: { credential: true, location: true }
    });

    if (!camera) throw new Error('Camera not found');
    if (camera.authMode === 'PASSWORD' && !camera.credential) {
      throw new Error('Camera credentials not configured');
    }

    // Audit log before anything else (exclude credentials)
    await tx.auditLog.create({
      data: {
        tenantId,
        actorId: user.id,
        actorType: 'USER',
        action: 'CAMERA_STREAM_ACCESSED',
        resource: 'CAMERA',
        resourceId: camera.id,
        metadata: { ipAddress: camera.ipAddress }
      }
    });

    const rawIpAddress = camera.ipAddress;
    
    // Fallback simple parsing for RTSP IP
    let hostname = rawIpAddress;
    let port = '554';
    let path = '/stream';
    if (rawIpAddress.includes('rtsp://')) {
       // if user passed a full URL, attempt to parse
       try {
         const parsed = new URL(rawIpAddress);
         hostname = parsed.hostname;
         port = parsed.port || '554';
         path = parsed.pathname + parsed.search;
       } catch {
         // ignore
       }
    } else if (rawIpAddress.includes(':')) {
       const parts = rawIpAddress.split(':');
       hostname = parts[0];
       port = parts[1].split('/')[0];
       path = '/' + (parts[1].split('/').slice(1).join('/') || 'stream');
    }

    // SSRF DNS Validation & Rebinding Protection
    const validatedIp = await validateAndResolveHostname(hostname);

    let rtspSource = '';
    if (camera.authMode === 'PASSWORD') {
      const username = decrypt(camera.credential!.encryptedUsername);
      const password = decrypt(camera.credential!.encryptedPassword);

      const encUser = encodeURIComponent(username);
      const encPass = encodeURIComponent(password);

      // Construct final safe RTSP URL using validated IP
      rtspSource = `rtsp://${encUser}:${encPass}@${validatedIp}:${port}${path.startsWith('/') ? path : '/' + path}`;
    } else {
      rtspSource = `rtsp://${validatedIp}:${port}${path.startsWith('/') ? path : '/' + path}`;
    }

    // Derive Opaque Path based on current streamVersion
    const initialStreamVersion = camera.streamVersion;
    const opaquePath = deriveOpaquePath(tenantId, camera.id, initialStreamVersion);

    // Provision MediaMTX Path
    try {
      const response = await fetch(`${ENV.mediamtxApiUrl}/v3/config/paths/add/${opaquePath}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          source: rtspSource,
          sourceOnDemand: true,
          sourceOnDemandCloseAfter: '60s',
          record: true,
          recordPath: `${ENV.cctvRecordingsRoot}/%path/%Y-%m-%d_%H-%M-%S.mp4`,
          recordFormat: 'fmp4',
          recordPartDuration: '15m',
          runOnRecordSegmentComplete: `curl -X POST http://app:3000/api/webhooks/mediamtx/record -H "Content-Type: application/json" -H "Authorization: Bearer ${ENV.mediamtxWebhookSecret}" -d "{\\"path\\":\\"$MTX_PATH\\",\\"file\\":\\"$MTX_SEGMENT_PATH\\"}"`
        }),
      });

      if (!response.ok) {
        if (response.status === 400) {
          let body;
          try {
            body = await response.json();
          } catch {
            throw new ProviderTransientError('MediaMTX API Error: HTTP 400 with non-JSON response');
          }
          
          if (!body || typeof body !== 'object' || !body.error) {
            throw new ProviderTransientError('MediaMTX API Error: HTTP 400 with missing error field');
          }
          
          if (body.error === 'path already exists') {
            // Intentional TOCTOU mitigation: Path already exists, safe to continue
          } else {
            Logger.error(`MediaMTX 400 error during path provisioning for camera`, new Error(String(body.error)), { cameraId: camera.id });
            throw new ProviderConfigurationError(`MediaMTX Config Error: ${body.error}`);
          }
        } else {
          throw new ProviderTransientError(`MediaMTX provisioning failed with status: ${response.status}`);
        }
      }
    } catch (errRaw: unknown) {
      const err = errRaw instanceof Error ? errRaw : new Error(String(errRaw));
      if (err.message && (err.message.startsWith('MediaMTX Config Error') || err.message.startsWith('MediaMTX API Error') || err.message.startsWith('MediaMTX provisioning failed'))) {
        throw err;
      }
      throw new ProviderTransientError('Internal stream provisioning error');
    }

    // Post-Provisioning Version Revalidation
    const currentCameraState = await tx.camera.findFirst({
      where: { id: camera.id, deletedAt: null },
      select: { streamVersion: true }
    });

    if (currentCameraState?.streamVersion !== initialStreamVersion) {
      // Race B mitigation: The streamVersion changed during MediaMTX provisioning.
      // 1. We must delete the newly provisioned stale path.
      await fetch(`${ENV.mediamtxApiUrl}/v3/config/paths/delete/${opaquePath}`, {
        method: 'DELETE'
      }).catch(() => {});
      // 2. We fail the request to prevent issuing a stale JWT.
      throw new Error('Camera configuration changed during stream provisioning. Please try again.');
    }

    // Lazy async cleanup (fail-soft)
    cleanupStalePaths(tenantId, camera.id, opaquePath).catch(err => {
      Logger.warn(`MediaMTX cleanup failed for camera`, { cameraId: camera.id, error: String(err?.message) });
    });

    // Generate JWT
    const jti = crypto.randomUUID();
    const payload = {
      sub: user.id,
      tenantId,
      cameraId: camera.id,
      streamVersion: initialStreamVersion,
      path: opaquePath,
      action: 'read'
    };

    const token = jwt.sign(payload, ENV.cctvStreamJwtSecret, {
      algorithm: 'HS256',
      expiresIn: '60s',
      jwtid: jti
    });

    // Returns explicitly defined WHEP proxy endpoint. Token is separated.
    const baseUrl = ENV.publicAppUrl;

    return {
      streamUrl: `${baseUrl}/api/cctv/cameras/${camera.id}/whep`,
      token: token
    };
  });
}

'use server';

import { requireAuth } from '@/lib/auth';
import { withTenant } from '@db/utils/prisma-tenant';
import { DistributedRateLimiter } from '@/lib/rate-limit/rate-limiter';
import { realtime } from '../adapter';

export async function heartbeatAction(status: 'ONLINE' | 'AWAY' | 'BUSY' = 'ONLINE') {
  const user = await requireAuth();

  // Bounded heartbeat frequency (max 10 per minute per user)
  const rl = await DistributedRateLimiter.checkLimit(user.tenantId, 'PRESENCE', 'HEARTBEAT', 10, 60, undefined, user.id);
  if (!rl.allowed) throw new Error('Too many requests');

  const prisma = withTenant(user.tenantId);

  // Upsert presence record securely using authenticated context
  const presence = await prisma.userPresence.upsert({
    where: { userId: user.id },
    create: {
      tenantId: user.tenantId,
      userId: user.id,
      status,
      lastSeenAt: new Date(),
    },
    update: {
      status,
      lastSeenAt: new Date(),
    }
  });

  // Publish presence update (Pusher presence channel handles connected clients natively,
  // but we can also broadcast a generic status update for graceful offline tracking).
  // E.g., broadcast to a tenant-wide presence observer channel if architected.

  return { success: true, data: presence };
}

export async function getPresenceAction(userIds: string[]) {
  const user = await requireAuth();

  // Rate limit
  const rl = await DistributedRateLimiter.checkLimit(user.tenantId, 'PRESENCE', 'GET_PRESENCE', 100, 60, undefined, user.id);
  if (!rl.allowed) throw new Error('Too many requests');

  const prisma = withTenant(user.tenantId);

  const presences = await prisma.userPresence.findMany({
    where: {
      userId: { in: userIds }
    }
  });

  return { success: true, data: presences };
}

