import { executeAsSystem, SystemOperation } from '@db/utils/prisma-system';
import { withTenant } from '@db/utils/prisma-tenant';

export interface RPOMetrics {
  tenantId: string;
  rpoPolicy: string;
  targetRPOHours: number;
  currentRPOHours: number | 'INFINITE';
  lastSuccessfulBackup: Date | null;
  status: 'GREEN' | 'YELLOW' | 'RED';
}

export class RPOMonitor {
  /**
   * Calculates RPO status for all tenants.
   */
  async getGlobalRPOStatus(): Promise<RPOMetrics[]> {
    return executeAsSystem(SystemOperation.DISASTER_RECOVERY, async (tx) => {
      const tenants = await tx.tenant.findMany({
        where: { status: { not: 'DELETED' } },
        select: { id: true, rpoPolicy: true }
      });

      // PostgreSQL DISTINCT ON guarantees the first row matching the ORDER BY clause
      const latestSnapshots = await tx.recoverySnapshot.findMany({
        where: { status: 'ACTIVE' },
        orderBy: { createdAt: 'desc' },
        distinct: ['tenantId'],
        select: { id: true, tenantId: true, createdAt: true }
      });

      const snapshotMap = new Map(latestSnapshots.map((s: any) => [s.tenantId, s]));
      const metrics: RPOMetrics[] = [];
      
      for (const tenant of tenants) {
        metrics.push(this.calculateRpoSync(tenant.id, tenant.rpoPolicy, snapshotMap.get(tenant.id) || null));
      }
      return metrics;
    });
  }

  /**
   * Calculates the exact RPO metric and health status for a single tenant using a provided snapshot.
   */
  calculateRpoSync(tenantId: string, policy: string = 'BASIC', latestSnapshot: { createdAt: Date } | null): RPOMetrics {
    let targetRPOHours = 24;
    if (policy === 'BUSINESS') targetRPOHours = 12;
    if (policy === 'ENTERPRISE') targetRPOHours = 1;

    if (!latestSnapshot) {
      return {
        tenantId,
        rpoPolicy: policy,
        targetRPOHours,
        currentRPOHours: 'INFINITE',
        lastSuccessfulBackup: null,
        status: 'RED'
      };
    }

    const msSinceBackup = Date.now() - latestSnapshot.createdAt.getTime();
    const currentRPOHours = msSinceBackup / (1000 * 60 * 60);

    let status: 'GREEN' | 'YELLOW' | 'RED' = 'GREEN';
    if (currentRPOHours > targetRPOHours * 2) {
      status = 'RED'; // Severely breached
    } else if (currentRPOHours > targetRPOHours) {
      status = 'YELLOW'; // Warning, breaching
    }

    return {
      tenantId,
      rpoPolicy: policy,
      targetRPOHours,
      currentRPOHours,
      lastSuccessfulBackup: latestSnapshot.createdAt,
      status
    };
  }

  /**
   * Calculates the exact RPO metric and health status for a single tenant dynamically.
   */
  async calculateRPO(tenantId: string, policy: string = 'BASIC'): Promise<RPOMetrics> {
    const tenantPrisma = withTenant(tenantId);
    const latestSnapshot = await tenantPrisma.recoverySnapshot.findFirst({
      where: { tenantId, status: 'ACTIVE' },
      orderBy: { createdAt: 'desc' },
      select: { createdAt: true }
    });

    return this.calculateRpoSync(tenantId, policy, latestSnapshot);
  }
}

import { executeAsSystem, SystemOperation } from '@db/utils/prisma-system';
import { withTenant } from '@db/utils/prisma-tenant';
import { getStorageProvider } from '../../../lib/storage';
import { Logger } from '@/lib/logger/logger';

 
// eslint-disable-next-line @typescript-eslint/no-unused-vars -- S2 Residual Debt: Legacy unused local
const POLICY_LIMITS: Record<string, number> = {
  DAILY: 7,
  WEEKLY: 4,
  MONTHLY: 12
};

export class RetentionPolicyService {
  /**
   * Enforces retention policies for all tenants based on their settings.
   */
  async enforceRetentionPolicies(): Promise<void> {
    const toDelete: any[] = [];
    
    // Step 1: Identify all snapshots to delete in a single bounded system transaction
    await executeAsSystem(SystemOperation.DISASTER_RECOVERY, async (tx) => {
      const tenants = await tx.tenant.findMany({
        where: { status: { not: 'DELETED' } },
        select: { id: true, rpoPolicy: true }
      });

      const allActiveSnapshots = await tx.recoverySnapshot.findMany({
        where: { status: 'ACTIVE' },
        orderBy: { createdAt: 'desc' },
        select: { id: true, tenantId: true, checksum: true }
      });

      const snapshotsByTenant = new Map<string, any[]>();
      for (const s of allActiveSnapshots) {
        if (!snapshotsByTenant.has(s.tenantId)) snapshotsByTenant.set(s.tenantId, []);
        snapshotsByTenant.get(s.tenantId)!.push(s);
      }

      for (const tenant of tenants) {
        let keepCount = 7; // Default Basic
        if (tenant.rpoPolicy === 'ENTERPRISE') keepCount = 30;
        if (tenant.rpoPolicy === 'BUSINESS') keepCount = 14;

        const snapshots = snapshotsByTenant.get(tenant.id) || [];
        if (snapshots.length > keepCount) {
          toDelete.push(...snapshots.slice(keepCount));
        }
      }
    });

    // Step 2: Perform external deletions safely outside the global transaction lock
    for (const snapshot of toDelete) {
      await this.deleteSnapshotSafely(snapshot);
    }
  }

  /**
   * Evaluates and prunes old snapshots for a single tenant manually.
   * Never deletes the most recent successful snapshot.
   */
  async enforceTenantRetention(tenantId: string): Promise<void> {
    let keepCount = 7; // Default Basic
    
    // Scoped local query for manual execution
    const toDelete = await executeAsSystem(SystemOperation.DISASTER_RECOVERY, async (tx) => {
      const tenant = await tx.tenant.findUnique({ where: { id: tenantId }, select: { rpoPolicy: true } });
      if (tenant?.rpoPolicy === 'ENTERPRISE') keepCount = 30;
      if (tenant?.rpoPolicy === 'BUSINESS') keepCount = 14;

      const snapshots = await tx.recoverySnapshot.findMany({
        where: { tenantId, status: 'ACTIVE' },
        orderBy: { createdAt: 'desc' },
        select: { id: true, tenantId: true, checksum: true }
      });

      if (snapshots.length <= keepCount) return [];
      return snapshots.slice(keepCount);
    });

    for (const snapshot of toDelete) {
      await this.deleteSnapshotSafely(snapshot);
    }
  }

  /**
   * Safely deletes a snapshot:
   * 1. Marks DELETE_PENDING atomically
   * 2. Audit record
   * 3. Deletes object storage
   * 4. Deletes DB metadata (or marks DELETED)
   // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: Legacy internal payload requires architectural typing
   */
  // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: Legacy internal payload requires architectural typing
  async deleteSnapshotSafely(snapshot: any, isRetry = false): Promise<void> {
    const storage = getStorageProvider();
    const tenantPrisma = withTenant(snapshot.tenantId);

    // 1. Mark DELETE_PENDING atomically to avoid TOCTOU races with other retention workers
    // Prisma does not return the updated row on updateMany, but it returns the count.
    const updateResult = await tenantPrisma.recoverySnapshot.updateMany({
      where: { 
        id: snapshot.id, 
        status: isRetry ? 'DELETE_PENDING' : 'ACTIVE' 
      },
      data: { status: 'DELETE_PENDING' }
    });

    if (updateResult.count === 0 && !isRetry) {
      // Snapshot was already transitioned (e.g. by another concurrent worker)
      return;
    }

    // We need to extract the objectKey from the checksum/id, but actually we need the `RecoveryJob` that created it to get the `archiveLocation`.
    // We don't have a direct link from RecoverySnapshot -> Job right now in the schema.
    // Let's find the job by checksum.
    const job = await tenantPrisma.recoveryJob.findFirst({
      where: { tenantId: snapshot.tenantId, checksum: snapshot.checksum, status: 'COMPLETED' }
    });

    if (!job || !job.archiveLocation) {
      // If we can't find the file location, just mark it as DELETED to clean up the DB
      await tenantPrisma.recoverySnapshot.update({
        where: { id: snapshot.id },
        data: { status: 'DELETED' }
      });
      return;
     
    }

    // eslint-disable-next-line @typescript-eslint/no-unused-vars -- S2 Residual Debt: Legacy unused local
    const [uri, query] = job.archiveLocation.split('?');
    let objectKey = '';
    
    if (uri.startsWith('local://')) {
      objectKey = uri.replace('local://', '').split('/')[1]; // format: local://tenantId/objectKey
    } else if (uri.startsWith('s3://')) {
      // s3://bucket/tenants/tenantId/recovery/objectKey
      const parts = uri.split('/');
      objectKey = parts[parts.length - 1];
    } else {
      // Unknown
      return;
    }

    try {
      // 3. Delete Object Storage
      const exists = await storage.verifyObjectExists(snapshot.tenantId, objectKey);
      if (exists) {
        await storage.deleteObject(snapshot.tenantId, objectKey);
      }
      
      // 4. Update DB
      await tenantPrisma.recoverySnapshot.update({
        where: { id: snapshot.id },
        data: { status: 'DELETED' }
      });

      await tenantPrisma.recoveryAuditLog.create({
        data: {
          tenantId: snapshot.tenantId,
          jobId: job.id,
          action: 'SNAPSHOT_RETENTION_DELETED',
          actorId: 'SYSTEM',
          metadata: { snapshotId: snapshot.id }
        }
      });
    } catch (eRaw: unknown) {
      const e = eRaw instanceof Error ? eRaw : new Error(String(eRaw));
      // Failsafe: leave in DELETE_PENDING, DO NOT delete database metadata.
      await tenantPrisma.recoveryAuditLog.create({
        data: {
          tenantId: snapshot.tenantId,
          jobId: job.id,
          action: 'RETENTION_DELETION_FAILED',
          actorId: 'SYSTEM',
          metadata: { snapshotId: snapshot.id, error: e.message }
        }
      });
      Logger.error('Failed to delete snapshot from storage:', e);
    }
  }

  /**
   * Resumes failed deletions (DELETE_PENDING)
   */
  async retryPendingDeletions(): Promise<void> {
    const pending = await executeAsSystem(SystemOperation.DISASTER_RECOVERY, async (tx) => tx.recoverySnapshot.findMany({
      where: { status: 'DELETE_PENDING' }
    }));

    for (const snapshot of pending) {
      await this.deleteSnapshotSafely(snapshot, true);
    }
  }
}

import { describe, it, expect, beforeAll, afterAll, vi } from 'vitest';
import { sendEmail } from '@/modules/communication/email/email.service';
import { createCall } from '@/modules/communication/telephony/telephony.service';
import { sendMessage } from '@/modules/communication/messaging/messaging.service';
import { executeAsSystem, SystemOperation } from '@db/utils/prisma-system';

vi.mock('@/lib/providers/provider.factory', () => ({
  ProviderFactory: {
    getEmailProvider: () => ({
      sendEmail: vi.fn().mockResolvedValue({ success: true, data: { id: 'test' } })
    }),
    getTelephonyProvider: () => ({
      makeCall: vi.fn().mockResolvedValue({ success: true, callId: 'test-call-id' })
    })
  }
}));

// Mock auth module
let mockUserId = '';
let mockTenantId = '';
let mockHasPermission = true;

vi.mock('@/lib/auth', () => ({
  requireAuth: vi.fn(async () => {}),
  requireTenant: vi.fn(async () => mockTenantId),
  requirePermission: vi.fn(async (resource, action) => {
    if (!mockHasPermission) throw new Error('Forbidden');
  })
}));

vi.mock('@/lib/tenant-context', () => ({
  getCurrentUserContext: vi.fn(async () => ({ id: mockUserId, tenantId: mockTenantId }))
}));

describe('Communication Services', () => {
  let testConversationId = '';

  beforeAll(async () => {
    await executeAsSystem(SystemOperation.SECURITY_AUDIT, async (tx) => {
      const tenant = await tx.tenant.create({ data: { name: 'Comm Test Tenant' } });
      const user = await tx.user.create({
        data: { clerkId: 'comm_test_' + Date.now(), email: `comm_${Date.now()}@test.com`, tenantId: tenant.id, status: 'ACTIVE' }
      });
      mockUserId = user.id;
      mockTenantId = tenant.id;

      // Create a real conversation for the happy-path sendMessage test
      const conv = await tx.chatConversation.create({
        data: {
          tenantId: tenant.id,
          type: 'DIRECT',
          participants: { create: [{ tenantId: tenant.id, userId: user.id, role: 'ADMIN' }] }
        }
      });
      testConversationId = conv.id;
    });
  });

  afterAll(async () => {
    await executeAsSystem(SystemOperation.SECURITY_AUDIT, async (tx) => {
      // AuditLog is append-only, and prevents Tenant/User deletion
      // We will leave the mock tenant and user in the test database
      await tx.callLog.deleteMany({ where: { tenantId: mockTenantId } });
      await tx.mailMessage.deleteMany({ where: { tenantId: mockTenantId } });
      await tx.mailThread.deleteMany({ where: { tenantId: mockTenantId } });
      await tx.chatMessage.deleteMany({ where: { tenantId: mockTenantId } });
      await tx.chatConversation.deleteMany({ where: { tenantId: mockTenantId } });
    });
  });

  it('should successfully send an email', async () => {
    mockHasPermission = true;
    const email = await sendEmail({ to: 'test@target.com', subject: 'Integration Test', bodyHtml: '<p>Test</p>' });
    expect(email).toBeDefined();
    expect((email.metadata as any).to).toBe('test@target.com');
    expect(email.tenantId).toBe(mockTenantId);
  });

  it('should successfully create a call log', async () => {
    mockHasPermission = true;
    const call = await createCall({ to: '+1234567890', from: '+0987654321' });
    expect(call).toBeDefined();
    expect(call.status).toBe('COMPLETED');
    expect(call.tenantId).toBe(mockTenantId);
  });

  it('should successfully send a message', async () => {
    mockHasPermission = true;
    // Uses the real testConversationId created in beforeAll (not a fake-id)
    const msg = await sendMessage({ conversationId: testConversationId, content: 'Test message', senderId: mockUserId });
    expect(msg).toBeDefined();
    expect(msg.content).toBe('Test message');
    expect(msg.tenantId).toBe(mockTenantId);
  });

  it('should reject communication when permission is denied', async () => {
    mockHasPermission = false;
    await expect(
      sendEmail({ to: 'test@target.com', subject: 'Fail Test', bodyHtml: '<p>Test</p>' })
    ).rejects.toThrow('Forbidden');
  });

  describe('Adversarial IDOR & Cross-Tenant Security', () => {
    let victimTenantId = '';
    let victimConversationId = '';
    
    beforeAll(async () => {
      await executeAsSystem(SystemOperation.SECURITY_AUDIT, async (tx) => {
        const vTenant = await tx.tenant.create({ data: { name: 'Victim Tenant' } });
        victimTenantId = vTenant.id;
        const vUser = await tx.user.create({
          data: { clerkId: 'victim_' + Date.now(), email: `victim_${Date.now()}@test.com`, tenantId: vTenant.id, status: 'ACTIVE' }
        });
        const conv = await tx.chatConversation.create({
          data: {
            tenantId: vTenant.id,
            type: 'DIRECT',
            participants: {
              create: [{ tenantId: vTenant.id, userId: vUser.id, role: 'ADMIN' }]
            }
          }
        });
        victimConversationId = conv.id;
      });
    });
    
    afterAll(async () => {
      await executeAsSystem(SystemOperation.SECURITY_AUDIT, async (tx) => {
        await tx.chatParticipant.deleteMany({ where: { tenantId: victimTenantId } });
        await tx.chatConversation.deleteMany({ where: { tenantId: victimTenantId } });
      });
    });

    it('should reject when attacker attempts to send message to victim conversation (IDOR)', async () => {
      mockHasPermission = true;
      mockTenantId = 'attacker-tenant-123'; // Attacker tenant context
      mockUserId = 'attacker-user-123';
      
      await expect(
        sendMessage({ conversationId: victimConversationId, content: 'Malicious payload', senderId: mockUserId })
      ).rejects.toThrow(); // Either 'Conversation not found' or 'Not authorized'
    });
  });
});

import { getCustomerTimeline } from '@/modules/crm/customer/customer.timeline.service';
import prisma from '@db/utils/prisma';
import { describe, it, expect, beforeAll, afterAll, beforeEach, afterEach, vi } from 'vitest';

// Mock auth dependencies
vi.mock('@/lib/auth', () => ({
  requireAuth: vi.fn(),
  requireTenant: vi.fn(),
  requirePermission: vi.fn(),
}));

import { withTenant } from '@db/utils/prisma-tenant';

// Use standard Prisma Client for test setup
describe('Customer Timeline Service', () => {
  let tenantId: string;
  let customerId: string;
  let userId: string;
  let otherCustomerId: string;

  beforeAll(async () => {
    // Generate isolated tenant for tests
    const tenant = await prisma.tenant.create({
      data: { name: 'Timeline Test Tenant' }
    });
    tenantId = tenant.id;

    const tenantPrisma = withTenant(tenantId);

    // Create user
    const user = await tenantPrisma.user.create({
      data: {
        tenantId,
        email: `tester-${Date.now()}@example.com`,
        firstName: 'Test',
        lastName: 'User',
      }
    });
    userId = user.id;

    // Create customers
    const customer = await tenantPrisma.customer.create({
      data: { tenantId, name: 'Main Customer', normalizedName: 'main customer' }
    });
    customerId = customer.id;

    const otherCustomer = await tenantPrisma.customer.create({
      data: { tenantId, name: 'Other Customer', normalizedName: 'other customer' }
    });
    otherCustomerId = otherCustomer.id;
  });

  afterAll(async () => {
    // Clean up
    const tenantPrisma = withTenant(tenantId);
    await tenantPrisma.cRMComment.deleteMany({ where: { tenantId } });
    await tenantPrisma.customer.deleteMany({ where: { tenantId } });
    await tenantPrisma.user.deleteMany({ where: { tenantId } });
    await prisma.tenant.delete({ where: { id: tenantId } });
  });

  beforeEach(async () => {
    vi.clearAllMocks();
    const auth = await import('@/lib/auth');
    (auth.requireAuth as any).mockResolvedValue({ id: userId, tenantId });
    (auth.requireTenant as any).mockResolvedValue(tenantId);
    (auth.requirePermission as any).mockResolvedValue(true);
  });

  afterEach(async () => {
    const tenantPrisma = withTenant(tenantId);
    await tenantPrisma.cRMComment.deleteMany({ where: { tenantId } });
  });

  it('should include CRMComments in the customer timeline', async () => {
    // Arrange
    const tenantPrisma = withTenant(tenantId);
    await tenantPrisma.cRMComment.create({
      data: {
        tenantId,
        userId,
        entityType: 'CUSTOMER',
        entityId: customerId,
        content: 'This is a test comment on the customer',
      }
    });

    // Act
    const result = await getCustomerTimeline({ customerId });

    // Assert
    expect(result.data.length).toBeGreaterThan(0);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const commentEvent = result.data.find((e: any) => e.description === 'This is a test comment on the customer');
    expect(commentEvent).toBeDefined();
    expect(commentEvent?.type).toBe('NOTE');
  });

  it('should exclude CRMComments from other customers', async () => {
    // Arrange
    const tenantPrisma = withTenant(tenantId);
    await tenantPrisma.cRMComment.create({
      data: {
        tenantId,
        userId,
        entityType: 'CUSTOMER',
        entityId: otherCustomerId, // Different customer
        content: 'This comment belongs to another customer',
      }
    });

    // Act
    const result = await getCustomerTimeline({ customerId });

    // Assert
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const commentEvent = result.data.find((e: any) => e.description === 'This comment belongs to another customer');
    expect(commentEvent).toBeUndefined();
  });

  it('should exclude CRMComments with deletedAt set (soft deleted)', async () => {
    // Arrange
    const tenantPrisma = withTenant(tenantId);
    await tenantPrisma.cRMComment.create({
      data: {
        tenantId,
        userId,
        entityType: 'CUSTOMER',
        entityId: customerId,
        content: 'This is a deleted comment',
        deletedAt: new Date(),
      }
    });

    // Act
    const result = await getCustomerTimeline({ customerId });

    // Assert
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const commentEvent = result.data.find((e: any) => e.description === 'This is a deleted comment');
    expect(commentEvent).toBeUndefined();
  });

  it('should exclude CRMComments for other entities (e.g. LEAD) with the same ID', async () => {
    // Arrange
    const tenantPrisma = withTenant(tenantId);
    await tenantPrisma.cRMComment.create({
      data: {
        tenantId,
        userId,
        entityType: 'LEAD', // Different entity type, same ID
        entityId: customerId,
        content: 'This comment belongs to a lead with a colliding ID',
      }
    });

    // Act
    const result = await getCustomerTimeline({ customerId });

    // Assert
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const commentEvent = result.data.find((e: any) => e.description === 'This comment belongs to a lead with a colliding ID');
    expect(commentEvent).toBeUndefined();
  });

  it('should sort timeline events deterministically (timestamp descending, then id ascending)', async () => {
    // Arrange: Create events with the exact same timestamp
    const now = new Date();
    const tenantPrisma = withTenant(tenantId);

    await tenantPrisma.cRMComment.create({
      data: {
        id: 'comment-1', // lexicographically smaller
        tenantId,
        userId,
        entityType: 'CUSTOMER',
        entityId: customerId,
        content: 'First comment',
        createdAt: now,
      }
    });

    await tenantPrisma.cRMComment.create({
      data: {
        id: 'comment-2', // lexicographically larger
        tenantId,
        userId,
        entityType: 'CUSTOMER',
        entityId: customerId,
        content: 'Second comment',
        createdAt: now,
      }
    });

    // Act
    const result = await getCustomerTimeline({ customerId });

    // Assert
    // Filter out only our test comments for precise checking
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const comments = result.data.filter((e: any) => e.id.startsWith('comment-'));
    expect(comments.length).toBe(2);
    // Since timestamp diff is 0, it falls back to a.id.localeCompare(b.id)
    // So comment-1 should come first.
    expect(comments[0].id).toBe('comment-1');
    expect(comments[1].id).toBe('comment-2');
  });
});

import { describe, it, expect } from 'vitest';
import crypto from 'crypto';
import { executeAsSystem, SystemOperation } from '@db/utils/prisma-system';
import prisma from '@db/utils/prisma';

describe('Diagnostic S4.2: System Bypass RLS Leak', () => {
  it('should not leak bypass_rls to normal prisma client', async () => {
    const tenantId = crypto.randomUUID();
    const customerId = crypto.randomUUID();

    // 1. Setup Data using System Prisma
    await executeAsSystem(SystemOperation.DEMO_SEED, async (tx) => {
      await tx.$executeRawUnsafe(`INSERT INTO "Tenant" (id, name, "createdAt", "updatedAt") VALUES ('${tenantId}', 'Diag Tenant', now(), now())`);
      await tx.$executeRawUnsafe(`INSERT INTO "Customer" (id, "tenantId", name, "normalizedName", "createdAt", "updatedAt") VALUES ('${customerId}', '${tenantId}', 'Diag Customer', 'diag customer', now(), now())`);
    });

    console.log("Data Seeded.");

    // 2. Query Data with unprivileged prisma
    const before = await prisma.customer.findMany({ where: { id: customerId } });
    console.log(`Before System Bypass: Found ${before.length} customers (Expected 0 due to RLS)`);

    // 3. Trigger Bypass
    await executeAsSystem(SystemOperation.SECURITY_AUDIT, async (tx) => {
      const inside = await tx.customer.findMany({ where: { id: customerId } });
      console.log(`Inside System Bypass: Found ${inside.length} customers (Expected 1)`);
      
      const pids: any[] = await tx.$queryRawUnsafe(`SELECT pg_backend_pid() as pid, current_setting('app.bypass_rls', true) as bypass`);
      console.log(`Inside System Bypass PID: ${pids[0].pid}, bypass: ${pids[0].bypass}`);
    });

    // 4. Query Data again with unprivileged prisma
    const after = await prisma.customer.findMany({ where: { id: customerId } });
    console.log(`After System Bypass: Found ${after.length} customers (Expected 0)`);
    
    const pids2: any[] = await prisma.$queryRawUnsafe(`SELECT pg_backend_pid() as pid, current_setting('app.bypass_rls', true) as bypass`);
    console.log(`Unprivileged Prisma PID: ${pids2[0].pid}, bypass: ${pids2[0].bypass}`);

    // Cleanup
    await executeAsSystem(SystemOperation.DEMO_SEED, async (tx) => {
      await tx.$executeRawUnsafe(`DELETE FROM "Customer" WHERE id = '${customerId}'`);
      await tx.$executeRawUnsafe(`DELETE FROM "Tenant" WHERE id = '${tenantId}'`);
    });
    
    expect(after.length).toBe(0);
  });
});

