    const result = await generateStreamToken(mockCameraId);
    expect(result.streamUrl).toBeDefined(); // Suppressed successfully
  });

  it("10b. Invalid Source 400 (Fails Closed)", async () => {
    setupPrismaMock({
      id: mockCameraId,
      ipAddress: "192.168.1.100",
      protocol: "RTSP",
      updatedAt: new Date(),
      credential: {
        id: "cred1",
        updatedAt: new Date(),
        encryptedUsername: "u",
        encryptedPassword: "p",
      },
    });
