    userA = await executeAsSystem(SystemOperation.SECURITY_AUDIT, async (tx) => await tx.user.create({
          data: { email: 'usera_deal@test.com', clerkId: 'clerk_a_deal', tenantId: tenantA.id, status: 'ACTIVE' }
