      });
    });
    
    const reactivatedUser = makeClerkUser(reactivatedClerkId, TARGET_NEW_EMAIL);
    const result = await ensureUserProvisioned(reactivatedUser);
    expect(result).not.toBeNull();
    expect(result!.id).toBe(testCrmUserId);
  });
});

