        return tx.auditLog.findMany({
          where: { tenantId: tenantA, action: 'LEAD_SCORE_UPDATED' }
        });
      });
      expect(logs.length).toBeGreaterThanOrEqual(1);
      expect(logs[0].actorType).toBe('AI');
    });
  });
});

